mapper.select:
SELECT s.id, s.nick_name, s.real_name, s.head_image, s.campus_id, c.campus_name, s.major, s.education, s.grade, s.skills, s.experience, s.expected_salary, s.expected_location, CASE WHEN #{jobId} IS NOT NULL THEN ( CASE WHEN j.required_major IS NOT NULL AND s.major LIKE CONCAT('%', j.required_major, '%') THEN 30 ELSE 0 END + CASE WHEN j.required_skills IS NOT NULL AND s.skills LIKE CONCAT('%', j.required_skills, '%') THEN 30 ELSE 0 END + CASE WHEN j.required_education IS NOT NULL AND s.education = j.required_education THEN 20 ELSE 0 END + CASE WHEN j.required_experience IS NOT NULL AND s.experience >= j.required_experience THEN 20 ELSE 0 END ) ELSE ( CASE WHEN #{requiredMajor} IS NOT NULL AND s.major LIKE CONCAT('%', #{requiredMajor}, '%') THEN 30 ELSE 0 END + CASE WHEN #{requiredSkills} IS NOT NULL AND s.skills LIKE CONCAT('%', #{requiredSkills}, '%') THEN 30 ELSE 0 END + CASE WHEN #{requiredEducation} IS NOT NULL AND s.education = #{requiredEducation} THEN 20 ELSE 0 END + CASE WHEN #{requiredExperience} IS NOT NULL AND s.experience >= #{requiredExperience} THEN 20 ELSE 0 END ) END AS match_score, CONCAT( CASE WHEN #{jobId} IS NOT NULL THEN CONCAT( CASE WHEN j.required_major IS NOT NULL AND s.major LIKE CONCAT('%', j.required_major, '%') THEN '专业匹配、' ELSE '' END, CASE WHEN j.required_skills IS NOT NULL AND s.skills LIKE CONCAT('%', j.required_skills, '%') THEN '技能匹配、' ELSE '' END, CASE WHEN j.required_education IS NOT NULL AND s.education = j.required_education THEN '学历匹配、' ELSE '' END, CASE WHEN j.required_experience IS NOT NULL AND s.experience >= j.required_experience THEN '经验匹配' ELSE '' END ) ELSE CONCAT( CASE WHEN #{requiredMajor} IS NOT NULL AND s.major LIKE CONCAT('%', #{requiredMajor}, '%') THEN '专业匹配、' ELSE '' END, CASE WHEN #{requiredSkills} IS NOT NULL AND s.skills LIKE CONCAT('%', #{requiredSkills}, '%') THEN '技能匹配、' ELSE '' END, CASE WHEN #{requiredEducation} IS NOT NULL AND s.education = #{requiredEducation} THEN '学历匹配、' ELSE '' END, CASE WHEN #{requiredExperience} IS NOT NULL AND s.experience >= #{requiredExperience} THEN '经验匹配' ELSE '' END ) END ) AS match_reason, s.create_time, s.update_time FROM student s LEFT JOIN campus c ON s.campus_id = c.id
LEFT JOIN job j ON j.id = #{jobId} AND j.enterprise_id = #{enterpriseId}
WHERE s.status = 1
AND ( (j.required_major IS NULL OR s.major LIKE CONCAT('%', j.required_major, '%')) OR (j.required_skills IS NULL OR s.skills LIKE CONCAT('%', j.required_skills, '%')) OR (j.required_education IS NULL OR s.education = j.required_education) OR (j.required_experience IS NULL OR s.experience >= j.required_experience) )
AND s.major LIKE CONCAT('%', #{requiredMajor}, '%')
AND s.skills LIKE CONCAT('%', #{requiredSkills}, '%')
AND s.education = #{requiredEducation}
AND s.experience >= #{requiredExperience}
AND s.campus_id = #{campusId}
ORDER BY match_score DESC, s.create_time DESC
